    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j]:
                c=g[i][j]; q=collections.deque([(i,j)]); seen[i][j]=True; cells=set()
                while q:
                    x,y=q.popleft(); cells.add((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and not seen[a][b] and g[a][b]==c:
                            seen[a][b]=True; q.append((a,b))
                out.append((c,len(cells)))
    return out
def denoise_compg(g):
    H,W=len(g),len(g[0]); o=[r[:] for r in g]
    cc=comps(g); keep=set(c for c,n in cc if n>=2)
    for i in range(H):
        nb=[]
        for di in(-1,0,1):
            for dj in(-1,0,1):
                a,b=i+di,j+dj
                if 0<=a<H and 0<=b<W and (di,dj)!=(0,0):
                    nb.append(g[a][b])
        cnt=Counter(nb); mx=max(cnt.values())
        cand=[c for c,v in cnt.items() if v==mx]
